import{_ as t,o,c as a,ag as d}from"./chunks/framework.By9v0nLp.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),s={name:"troubleshooting.md"};function i(n,e,r,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Nostalgic Dialog checks your files when they load and writes what it finds to the game log (<code>logs/latest.log</code>). Most problems are explained there.</p><h2 id="reading-the-log" tabindex="-1">Reading the log <a class="header-anchor" href="#reading-the-log" aria-label="Permalink to &quot;Reading the log&quot;">​</a></h2><p>After starting a world or running <code>/reload</code>, look for lines from <code>nostalgicdialog</code>. A healthy load looks like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[com.nostalgicdialog.NostalgicDialog/]: Loaded 3 speakers</span></span>
<span class="line"><span>[com.nostalgicdialog.NostalgicDialog/]: Loaded 5 dialogs</span></span></code></pre></div><p>If the numbers are lower than the files you made, one of them didn&#39;t load. The reason is a few lines above.</p><h2 id="messages-and-what-to-do" tabindex="-1">Messages and what to do <a class="header-anchor" href="#messages-and-what-to-do" aria-label="Permalink to &quot;Messages and what to do&quot;">​</a></h2><h3 id="when-files-load" tabindex="-1">When files load <a class="header-anchor" href="#when-files-load" aria-label="Permalink to &quot;When files load&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Message</th><th>Meaning</th><th>Fix</th></tr></thead><tbody><tr><td><code>Couldn&#39;t load dialog mypack:elder: ...</code></td><td>The file has a mistake, so it was skipped. The end of the message says what</td><td>Check the field it names. Common causes: a missing comma, a typo in a field name, <code>&quot;type&quot;</code> misspelled</td></tr><tr><td><code>Couldn&#39;t load speaker mypack:elder: ...</code></td><td>Same, for a speaker file</td><td>As above</td></tr><tr><td><code>Unknown condition type &#39;flags&#39;. Known: [...]</code></td><td>A condition&#39;s <code>type</code> doesn&#39;t exist</td><td>Use one of the listed types. See <a href="/wiki/nostalgicdialog/logic/conditions">Conditions</a></td></tr><tr><td><code>Unknown action type &#39;giv&#39;. Known: [...]</code></td><td>An action&#39;s <code>type</code> doesn&#39;t exist</td><td>See <a href="/wiki/nostalgicdialog/logic/actions">Actions</a></td></tr><tr><td><code>Dialog mypack:elder: start node &#39;start&#39; doesn&#39;t exist</code></td><td>There&#39;s no node with the <code>start</code> name</td><td>Add a node called <code>start</code>, or set <code>&quot;start&quot;</code> to your first node&#39;s name</td></tr><tr><td><code>Dialog mypack:elder: node &#39;menu&#39; goes to &#39;vilage&#39;, which doesn&#39;t exist</code></td><td>A <code>goto</code> or <code>next</code> has a typo</td><td>Fix the node name. <code>end</code> is always allowed</td></tr><tr><td><code>Dialog mypack:elder: node &#39;menu&#39; uses speaker mypack:eldr, which doesn&#39;t exist (narrator is used instead)</code></td><td>The speaker name is wrong, or the speaker file failed to load</td><td>Fix the name, or check the speaker&#39;s own load message</td></tr></tbody></table><h3 id="during-a-conversation" tabindex="-1">During a conversation <a class="header-anchor" href="#during-a-conversation" aria-label="Permalink to &quot;During a conversation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Message</th><th>Meaning</th><th>Fix</th></tr></thead><tbody><tr><td><code>Can&#39;t start dialog mypack:elder for Steve: it doesn&#39;t exist</code></td><td>The id in the command or binding is wrong, or the file failed to load</td><td>Check the id with <code>/dialog list</code></td></tr><tr><td><code>Dialog mypack:elder has no node &#39;x&#39;; ending it</code></td><td>The conversation tried to go to a node that isn&#39;t there</td><td>Fix the <code>goto</code> (it&#39;s also reported at load time)</td></tr><tr><td><code>Dialog mypack:elder went through 64 nodes without showing anything (a loop?); ending it</code></td><td><a href="/wiki/nostalgicdialog/guide/dialogs#logic-nodes">Logic nodes</a> point at each other in a circle</td><td>Make sure every chain reaches a node with lines, or <code>end</code></td></tr><tr><td><code>Dialog &#39;give&#39; needs an item id, not #c:gems</code></td><td>A <code>give</code> action uses a tag</td><td>Give a specific item id</td></tr><tr><td><code>Dialog command &#39;xyz&#39; failed</code></td><td>A <code>command</code> action threw an error</td><td>Test the command in chat, without the <code>/</code> in the JSON</td></tr><tr><td><code>Dialog tried to grant memory mypack:fire, but Nostalgic Memories isn&#39;t installed</code></td><td>A <code>memory</code> action ran without that mod</td><td>Install Nostalgic Memories, or remove the action</td></tr></tbody></table><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><p><strong>My changes don&#39;t show up.</strong> Run <code>/reload</code> after editing dialog and speaker files. Portrait images and sounds are part of the resource pack, so those need <strong>F3 + T</strong> (reload resource packs) instead.</p><p><strong>The portrait is a purple and black square.</strong> The image path is wrong. <code>mypack:textures/portrait/elder.png</code> must be at <code>assets/mypack/textures/portrait/elder.png</code> in a resource pack. See <a href="/wiki/nostalgicdialog/guide/speakers#making-portrait-images">Portraits</a>.</p><p><strong>A choice never shows up.</strong> Its <code>conditions</code> don&#39;t pass. Check the player&#39;s data with <code>/dialog info &lt;player&gt;</code>. If the answer should show but be unpickable, use <code>requires</code> instead. See <a href="/wiki/nostalgicdialog/guide/choices#hidden-or-greyed-out">Choices</a>.</p><p><strong>The conversation skips my question.</strong> If every visible answer is greyed out, the mod skips the question so the player can&#39;t get stuck. Make sure at least one answer, such as &quot;Never mind.&quot;, has no <code>requires</code>.</p><p><strong>The text stays slow (or fast).</strong> A <code>{speed:x}</code> tag lasts until another one changes it, even into the next box. End slow parts with <code>{speed:1}</code>.</p><p><strong>Right-clicking the NPC opens trades instead of talking.</strong> The binding is missing. Bind it again with <code>/dialog bind</code>, and check the selector picked the right entity.</p><p><strong>The conversation ends by itself.</strong> A conversation with a bound character ends when the player is more than 8 blocks away, the character dies, or one of them changes dimension. To teleport during a conversation, see <a href="/wiki/nostalgicdialog/using/starting#teleporting-during-a-conversation">Teleporting during a conversation</a>.</p><p><strong>A tag shows up as text, like <code>{shkae}</code>.</strong> The mod didn&#39;t recognize it, so it&#39;s shown as written. Check the spelling against <a href="/wiki/nostalgicdialog/guide/text-tags">Text Tags</a>.</p><p><strong>Players on my server don&#39;t see portraits.</strong> Portraits live in the resource pack. Players need it too, see the <a href="/wiki/nostalgicdialog/guide/speakers#making-portrait-images">note on servers</a>.</p>`,21)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
